import Component from 'flarum/common/Component';
export default class CoachBio extends Component {
  view() {
    const user = this.attrs?.user;
    const teams = user?.teams();
    let placeholder = m("div", {
      className: "CoachBio"
    });
    if (teams && teams.length > 0) {
      const team = teams[0];
      const race = team.race();
      placeholder = m("div", {
        className: "CoachBio"
      }, m("a", {
        className: "CoachBio-team",
        href: `https://www.lutececup.org/index.php?page=15&team_id=${team.id()}`,
        title: "Voir le roster"
      }, m("object", {
        class: "Avatar",
        data: `https://www.lutececup.org/img/blason/blason_${team.id()}.jpg`,
        type: "image/jpg"
      }, m("img", {
        class: "Avatar",
        src: `https://www.lutececup.org/img/logo/race_${race ? race.id() : ''}.gif`
      })), m("span", null, team.team_nom()), m("span", null, "(", race ? race.race_nom() : '', ")")));
    }
    return placeholder;
  }
}
flarum.reg.add('gerardwalace-bb-hub-coach-bio', 'forum/components/CoachBio', CoachBio);